import{_ as r,o,c as a,a2 as t}from"./chunks/framework.CiKk3sJz.js";const f=JSON.parse('{"title":"漫画 · 第 17 话 Web Workers：后台线程解冻页面","description":"","frontmatter":{},"headers":[],"relativePath":"comics/html/EP.17-web-workers.md","filePath":"comics/html/EP.17-web-workers.md","lastUpdated":1792579602000}'),s={name:"comics/html/EP.17-web-workers.md"};function l(d,e,i,n,c,h){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="漫画-·-第-17-话-web-workers-后台线程解冻页面" tabindex="-1">漫画 · 第 17 话 Web Workers：后台线程解冻页面 <a class="header-anchor" href="#漫画-·-第-17-话-web-workers-后台线程解冻页面" aria-label="Permalink to &quot;漫画 · 第 17 话 Web Workers：后台线程解冻页面&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/html/06-web-workers">docs/html/06-web-workers.md</a> ｜ 原画：<a href="./EP.17-web-workers.svg">EP.17-web-workers.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，页面上放了个 60fps 旋转方块当装饰，结果&quot;导出报表&quot;按钮一点——方块当场冻住，按钮转圈也没了，整个页面假死好几秒。</li><li><strong>标签君</strong>：HTML5 结构师，本话主角。开了一条 Worker 后台线程，把 4000 万次累加和像素处理都丢进去，主线程只管 UI。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>JS 是单线程的，事件循环同一时刻只跑一个任务；CPU 密集型长任务（大循环、逐像素处理、几十万行排序）一旦超过 500ms，动画掉帧、点击无响应、输入卡顿。Web Worker 提供真正的后台 OS 线程：主线程与 Worker 不共享任何变量，只通过 <code>postMessage</code> 传递消息，Worker 里没有 DOM、没有 window，只负责算。注意它解决的是 CPU 瓶颈——fetch、定时器的等待本来就不占主线程。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>主线程被一个同步大循环占住后，事件循环里排队的动画帧、点击回调、输入事件全部无法执行，表现为页面&quot;假死&quot;。这类问题无法靠异步回调解决——代码本身在持续吃 CPU。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p><code>new Worker(url)</code> 启动独立执行环境，有自己的事件循环与全局对象 <code>self</code>，无 <code>window</code>/<code>document</code>。两边靠消息队列通信：主线程 <code>postMessage</code> 投递、Worker 的 <code>self.onmessage</code> 处理、算完再 <code>self.postMessage</code> 回传，全程异步。消息默认走<strong>结构化克隆</strong>深拷贝：支持普通对象、Map/Set、ArrayBuffer、ImageData；不支持函数、DOM 节点，class 实例克隆后丢原型变纯数据——所以约定 <code>{type, payload}</code> 消息协议。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>三个工程要点：①<strong>Blob URL 内联 Worker</strong>——<code>new Worker(&#39;./a.js&#39;)</code> 在 file:// 下被同源策略拒绝，把代码放字符串里 <code>URL.createObjectURL(new Blob([code]))</code> 双击即可运行，工程环境再用独立文件；②<strong>Transferable</strong>——<code>postMessage(buf, [buf])</code> 转移 ArrayBuffer 所有权实现零拷贝，适合几十 MB 的 ImageData 像素，但转移后主线程的 buf 立即变空（byteLength=0），用完再转移回来；③<strong>Promise 化封装</strong>——自增 id 关联请求与回包，业务层 <code>await pw.invoke({type:&#39;sort&#39;, data})</code>；<code>onerror</code> 必挂（Worker 异常不会出现在主线程控制台）、配超时 reject、用完 <code>terminate()</code> 回收。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>Worker 解决 CPU 密集而非网络等待；无 DOM、不共享变量，只靠 postMessage 结构化克隆通信。</li><li>大 buffer 用 Transferable 转移而非拷贝，转移后原引用 byteLength=0；消息只传纯数据。</li><li>file:// 用 Blob 内联 Worker；onerror 必挂、超时保护、terminate 回收一个都不能少。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：把一个 8MB 的 ArrayBuffer <code>postMessage(buf, [buf])</code> 发给 Worker 后，主线程紧接着读 <code>buf.byteLength</code> 得到什么？如果后面还要用这块数据该怎么办？</p><p><strong>答</strong>：得到 <code>0</code>。Transferable 的语义是<strong>转移所有权</strong>而非拷贝：buffer 的底层内存直接移交给接收方，发送方的引用立刻变为&quot;已分离&quot;的空 buffer，再读写都没有数据（所以规范上应立即把该引用置 null，防止误用）。如果主线程后面还需要数据，标准做法是让 Worker 处理完后把同一个 buffer 再通过 <code>postMessage(result, [buffer])</code> 转移回来，所有权重新回到主线程；只是想让两边都能看到同一份数据且不能接受&quot;失去所有权&quot;的场景，才用默认的克隆传递（付出复制成本）。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>Blob 内联 Worker：主线程长任务卡死动画 vs Worker 后台计算对比：<a href="./../../examples/html/06-web-workers/index-01-blob-worker-calc.html">examples/html/06-web-workers/index-01-blob-worker-calc.html</a></li><li>Transferable 像素处理：ArrayBuffer 零拷贝转移 + Worker 内灰度/反色：<a href="./../../examples/html/06-web-workers/index-02-transferable-pixels.html">index-02-transferable-pixels.html</a></li><li>Promise 化通信：invoke 封装 + 排序任务队列 + 错误传递：<a href="./../../examples/html/06-web-workers/index-03-promise-worker.html">index-03-promise-worker.html</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 18 话《Geolocation》——经纬度到手前先过三关：安全上下文、用户授权、还有几百米的坐标系偏移。</p>',22)])])}const u=r(s,[["render",l]]);export{f as __pageData,u as default};
